  [("calzado adecuado", "zapatillas firmes, ajustadas y con suela que no resbale"), ("capas", "varias prendas finas que se pueden sacar o poner"), ("impermeable", "que no deja pasar el agua"), ("canilleras", "protectores de las piernas para el fútbol"), ("ajustado", "bien puesto, ni muy suelto ni muy apretado")],
