  [ex("Hace mucho calor. ¿Qué eliges: A) ropa liviana de colores claros, gorro y protector solar, B) ropa oscura y gruesa?", "A", "Protege del calor y del sol."),
   ex("Vas en bicicleta. ¿Qué usas en la cabeza: casco o gorro de lana?", "Casco", "Protege la cabeza."),
   ex("Tu pantalón es tan largo que se arrastra por el suelo. ¿Qué haces: A) lo arreglas o cambias de ropa, B) corres así?", "A", "Puedes tropezar y caer.")],
